+{"id":"B88","cmd":"git commit -q -F - <<'EOF'\nfix(fence): the FR-6 classifier stops blocking prose that mentions rm -rf src in a NOTES heredoc\nEOF","expect":"allow","rule":"FR-6","why":"a commit message read from stdin naming a destructive command mid-sentence","cwd":"repo"}
